app_css:
.tool-app-dripdesk { color: #1a2e05; max-width: 880px; margin-inline: auto; }
.tool-app-dripdesk .dd-wrap { display: grid; gap: 14px; }
.tool-app-dripdesk .dd-card { background: #f7fee7; border: 1px solid #d9f99d; border-radius: 14px; padding: 16px; }
.tool-app-dripdesk .dd-card > h3 { margin: 0 0 10px; font-size: 16px; color: #365314; }
.tool-app-dripdesk .dd-card > h4 { margin: 14px 0 8px; font-size: 12px; color: #4d7c0f; text-transform: uppercase; letter-spacing: .06em; }
.tool-app-dripdesk .dd-row { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; margin: 10px 0; }
.tool-app-dripdesk .dd-grow { flex: 1 1 200px; }
.tool-app-dripdesk label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; color: #365314; }
.tool-app-dripdesk input[type="text"], .tool-app-dripdesk input[type="number"], .tool-app-dripdesk select { border: 1px solid #bef264; border-radius: 8px; padding: 8px 10px; font-size: 14px; background: #fff; color: #1a2e05; width: 100%; box-sizing: border-box; }
.tool-app-dripdesk .dd-table { width: 100%; border-collapse: collapse; margin: 8px 0; background: #fff; border-radius: 10px; overflow: hidden; }
.tool-app-dripdesk .dd-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: #4d7c0f; padding: 8px; background: #ecfccb; }
.tool-app-dripdesk .dd-table td { padding: 6px 8px; border-top: 1px solid #ecfccb; font-size: 14px; vertical-align: middle; }
.tool-app-dripdesk .dd-table .dd-dose, .tool-app-dripdesk .dd-table .dd-qty, .tool-app-dripdesk .dd-table .dd-libcost { max-width: 110px; }
.tool-app-dripdesk .dd-linetotal, .tool-app-dripdesk .dd-unitcost { font-weight: 700; white-space: nowrap; }
.tool-app-dripdesk .dd-btn { background: #65A30D; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; white-space: nowrap; }
.tool-app-dripdesk .dd-btn:hover { background: #4d7c0f; }
.tool-app-dripdesk .dd-btn-ghost { background: #ecfccb; color: #3f6212; }
.tool-app-dripdesk .dd-btn-ghost:hover { background: #d9f99d; }
.tool-app-dripdesk .dd-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin: 10px 0; }
.tool-app-dripdesk .dd-stat { background: #fff; border: 1px solid #d9f99d; border-radius: 10px; padding: 10px 12px; display: flex; flex-direction: column; gap: 2px; }
.tool-app-dripdesk .dd-stat > span { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: #4d7c0f; font-weight: 700; }
.tool-app-dripdesk .dd-stat strong { font-size: 20px; color: #1a2e05; }
.tool-app-dripdesk .dd-suggest { display: flex; flex-direction: column; gap: 2px; }
.tool-app-dripdesk .dd-suggest span { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: #4d7c0f; font-weight: 700; }
.tool-app-dripdesk .dd-suggest strong { font-size: 22px; color: #4d7c0f; }
.tool-app-dripdesk .dd-templates { display: flex; flex-wrap: wrap; gap: 8px; }
.tool-app-dripdesk .dd-templates button { background: #fff; border: 1px solid #bef264; border-radius: 999px; padding: 7px 14px; font-size: 13px; font-weight: 600; color: #3f6212; cursor: pointer; }
.tool-app-dripdesk .dd-templates button:hover { background: #ecfccb; }
.tool-app-dripdesk .dd-remove { background: none; border: none; color: #b91c1c; font-size: 20px; cursor: pointer; padding: 0 4px; }
.tool-app-dripdesk .dd-saved-list { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-dripdesk .dd-saved-list li { display: flex; justify-content: space-between; align-items: center; gap: 8px; background: #fff; border: 1px solid #d9f99d; border-radius: 10px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; }
.tool-app-dripdesk button.dd-load { background: none; border: none; color: #4d7c0f; font-weight: 700; cursor: pointer; text-align: left; font-size: 14px; padding: 0; }
.tool-app-dripdesk button.dd-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 18px; padding: 0 2px; }
.tool-app-dripdesk .dd-hint { font-size: 13px; color: #4d7c0f; margin: 0 0 8px; }
.tool-app-dripdesk .dd-empty { font-size: 13px; color: #4d7c0f; margin: 6px 0; }
.tool-app-dripdesk .dd-file { cursor: pointer; display: inline-flex; align-items: center; }
.tool-app-dripdesk .dd-menu-item { display: flex; gap: 10px; align-items: center; background: #fff; border: 1px solid #d9f99d; border-radius: 10px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; }
.tool-app-dripdesk .dd-menu-item label { flex-direction: row; align-items: center; gap: 10px; flex: 1; font-size: 14px; font-weight: 600; color: #1a2e05; cursor: pointer; }
.tool-app-dripdesk .dd-menu-item input[type="checkbox"] { width: 18px; height: 18px; accent-color: #65A30D; }
.tool-app-dripdesk .dd-menu-item strong { color: #4d7c0f; white-space: nowrap; }
.tool-app-dripdesk .dd-print { display: none; }
@media print {
  .tool-app-dripdesk .dd-wrap { display: none !important; }
  .tool-app-dripdesk .dd-print { display: block !important; color: #000; }
  .tool-app-dripdesk .dd-print h1 { font-size: 28px; margin: 0 0 4px; }
  .tool-app-dripdesk .dd-print .dd-print-date { color: #555; font-size: 13px; margin: 0 0 16px; }
  .tool-app-dripdesk .dd-print-item { padding: 10px 0; border-bottom: 1px solid #bbb; }
  .tool-app-dripdesk .dd-print-item .dd-print-top { display: flex; justify-content: space-between; align-items: baseline; }
  .tool-app-dripdesk .dd-print-item strong { font-size: 17px; }
  .tool-app-dripdesk .dd-print-item .dd-print-ing { font-size: 12px; color: #555; margin-top: 3px; }
  .tool-app-dripdesk .dd-print-note { font-size: 12px; color: #555; margin-top: 16px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function num(v) { var n = parseFloat(v); return isFinite(n) ? n : 0; }

  var LS_LIB = 'toolapp-dripdesk-lib';
  var LS_FORMULAS = 'toolapp-dripdesk-formulas';
  var LS_MENU = 'toolapp-dripdesk-menu';

  var DEFAULT_LIB = [
    { name: "Normal Saline 500ml", unit: "bag", cost: 3.50 },
    { name: "Normal Saline 1000ml", unit: "bag", cost: 5.00 },
    { name: "Lactated Ringer's 500ml", unit: "bag", cost: 4.00 },
    { name: "Lactated Ringer's 1000ml", unit: "bag", cost: 5.50 },
    { name: "Vitamin C", unit: "5g dose", cost: 8.00 },
    { name: "B-Complex", unit: "10ml vial", cost: 6.00 },
    { name: "B12 (methylcobalamin)", unit: "5mg dose", cost: 4.50 },
    { name: "Magnesium chloride", unit: "2ml dose", cost: 3.00 },
    { name: "Zinc sulfate", unit: "dose", cost: 3.50 },
    { name: "Calcium gluconate", unit: "dose", cost: 4.00 },
    { name: "Glutathione", unit: "2000mg dose", cost: 28.00 },
    { name: "NAD+", unit: "500mg dose", cost: 85.00 },
    { name: "CoQ10", unit: "100mg dose", cost: 6.50 },
    { name: "L-Carnitine", unit: "1g dose", cost: 7.00 },
    { name: "Amino acid blend", unit: "dose", cost: 12.00 },
    { name: "Biotin", unit: "5mg dose", cost: 5.00 },
    { name: "Folic acid", unit: "1mg dose", cost: 3.00 },
    { name: "Vitamin D3", unit: "50k IU dose", cost: 4.00 },
    { name: "Toradol", unit: "30mg dose", cost: 5.00 },
    { name: "Zofran", unit: "4mg dose", cost: 4.50 },
    { name: "Pepcid", unit: "20mg dose", cost: 3.50 },
    { name: "Benadryl", unit: "25mg dose", cost: 3.00 },
    { name: "Taurine", unit: "1g dose", cost: 5.00 },
    { name: "Procaine 1%", unit: "10ml vial", cost: 6.00 }
  ];

  var TEMPLATES = [
    { name: "Hydration Rescue", items: [
      { name: "Normal Saline 1000ml", dose: "1 bag", qty: 1 },
      { name: "B-Complex", dose: "1 vial", qty: 1 },
      { name: "Magnesium chloride", dose: "1 dose", qty: 1 },
      { name: "B12 (methylcobalamin)", dose: "1 dose", qty: 1 }
    ] },
    { name: "Immunity Boost", items: [
      { name: "Normal Saline 1000ml", dose: "1 bag", qty: 1 },
      { name: "Vitamin C", dose: "5g", qty: 1 },
      { name: "Zinc sulfate", dose: "1 dose", qty: 1 },
      { name: "B-Complex", dose: "1 vial", qty: 1 },
      { name: "B12 (methylcobalamin)", dose: "1 dose", qty: 1 }
    ] },
    { name: "Beauty Glow", items: [
      { name: "Normal Saline 500ml", dose: "1 bag", qty: 1 },
      { name: "Glutathione", dose: "2000mg", qty: 1 },
      { name: "Vitamin C", dose: "5g", qty: 1 },
      { name: "Biotin", dose: "5mg", qty: 1 },
      { name: "B12 (methylcobalamin)", dose: "1 dose", qty: 1 }
    ] },
    { name: "Energy Surge", items: [
      { name: "Normal Saline 1000ml", dose: "1 bag", qty: 1 },
      { name: "B12 (methylcobalamin)", dose: "1 dose", qty: 1 },
      { name: "B-Complex", dose: "1 vial", qty: 1 },
      { name: "L-Carnitine", dose: "1g", qty: 1 },
      { name: "Taurine", dose: "1g", qty: 1 }
    ] },
    { name: "Athletic Recovery", items: [
      { name: "Lactated Ringer's 1000ml", dose: "1 bag", qty: 1 },
      { name: "Amino acid blend", dose: "1 dose", qty: 1 },
      { name: "Magnesium chloride", dose: "1 dose", qty: 1 },
      { name: "Vitamin C", dose: "5g", qty: 1 },
      { name: "B12 (methylcobalamin)", dose: "1 dose", qty: 1 }
    ] },
    { name: "Migraine Relief", items: [
      { name: "Normal Saline 500ml", dose: "1 bag", qty: 1 },
      { name: "Toradol", dose: "30mg", qty: 1 },
      { name: "Zofran", dose: "4mg", qty: 1 },
      { name: "Pepcid", dose: "20mg", qty: 1 },
      { name: "Magnesium chloride", dose: "1 dose", qty: 1 }
    ] },
    { name: "NAD+ Longevity", items: [
      { name: "Normal Saline 500ml", dose: "1 bag", qty: 1 },
      { name: "NAD+", dose: "500mg", qty: 1 }
    ] }
  ];

  function load(key, fallback) {
    try { var v = JSON.parse(localStorage.getItem(key)); return v == null ? fallback : v; }
    catch (e) { return fallback; }
  }
  function save(key, val) {
    try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {}
  }

  var lib = load(LS_LIB, null);
  if (!Array.isArray(lib) || !lib.length) lib = DEFAULT_LIB.slice();
  var formulas = load(LS_FORMULAS, null) || {};
  var menuChecks = load(LS_MENU, null) || {};
  var lines = []; // {name, dose, qty, unitCost}

  function libEntry(name) {
    for (var i = 0; i < lib.length; i++) if (lib[i].name === name) return lib[i];
    return null;
  }
  function unitCostFor(line) {
    var e = libEntry(line.name);
    return e ? num(e.cost) : num(line.unitCost);
  }

  function renderLibSelect() {
    var sel = $('dd-ing-select');
    sel.innerHTML = '';
    lib.forEach(function (ing) {
      var o = document.createElement('option');
      o.value = ing.name;
      o.textContent = ing.name + ' (' + ing.unit + ' \u2014 ' + money(ing.cost) + ')';
      sel.appendChild(o);
    });
  }

  function renderLines() {
    var tb = $('dd-lines');
    tb.innerHTML = '';
    lines.forEach(function (line, idx) {
      var tr = document.createElement('tr');
      tr.setAttribute('data-idx', idx);
      var tdName = document.createElement('td');
      tdName.textContent = line.name;
      var tdDose = document.createElement('td');
      var dose = document.createElement('input');
      dose.type = 'text'; dose.className = 'dd-dose'; dose.value = line.dose || '';
      dose.placeholder = 'e.g. 5g'; dose.setAttribute('aria-label', 'Dose for ' + line.name);
      tdDose.appendChild(dose);
      var tdQty = document.createElement('td');
      var qty = document.createElement('input');
      qty.type = 'number'; qty.className = 'dd-qty'; qty.min = '0'; qty.step = '0.5';
      qty.value = line.qty == null ? 1 : line.qty;
      qty.setAttribute('aria-label', 'Quantity for ' + line.name);
      tdQty.appendChild(qty);
      var tdUnit = document.createElement('td');
      tdUnit.className = 'dd-unitcost';
      tdUnit.textContent = money(unitCostFor(line));
      var tdTotal = document.createElement('td');
      tdTotal.className = 'dd-linetotal';
      tdTotal.textContent = money(num(qty.value) * unitCostFor(line));
      var tdX = document.createElement('td');
      var x = document.createElement('button');
      x.type = 'button'; x.className = 'dd-remove';
      x.setAttribute('data-idx', idx); x.setAttribute('aria-label', 'Remove ' + line.name);
      x.textContent = '\u00d7';
      tdX.appendChild(x);
      tr.appendChild(tdName); tr.appendChild(tdDose); tr.appendChild(tdQty);
      tr.appendChild(tdUnit); tr.appendChild(tdTotal); tr.appendChild(tdX);
      tb.appendChild(tr);
    });
    $('dd-empty').style.display = lines.length ? 'none' : 'block';
  }

  function lineCost(i) { return num(lines[i].qty) * unitCostFor(lines[i]); }

  function recalc() {
    var ingCost = 0, i;
    for (i = 0; i < lines.length; i++) ingCost += lineCost(i);
    var fee = num($('dd-fee').value);
    var total = ingCost + fee;
    $('dd-ingcost').textContent = money(ingCost);
    $('dd-cost').textContent = money(total);
    var target = num($('dd-margin-target').value);
    var suggest = (target > 0 && target < 100) ? total / (1 - target / 100) : total;
    $('dd-suggest').textContent = money(suggest);
    var price = num($('dd-price').value);
    var profit = price - total;
    var pct = price > 0 ? (profit / price * 100) : 0;
    $('dd-margin').textContent = money(profit) + ' \u00b7 ' + pct.toFixed(1) + '%';
    var rows = $('dd-lines').querySelectorAll('tr');
    for (i = 0; i < rows.length && i < lines.length; i++) {
      rows[i].querySelector('.dd-unitcost').textContent = money(unitCostFor(lines[i]));
      rows[i].querySelector('.dd-linetotal').textContent = money(lineCost(i));
    }
  }

  function refreshLineCosts() {
    lines.forEach(function (line) { line.unitCost = unitCostFor(line); });
  }

  function renderTemplates() {
    var wrap = $('dd-templates');
    wrap.innerHTML = '';
    TEMPLATES.forEach(function (t, idx) {
      var b = document.createElement('button');
      b.type = 'button'; b.setAttribute('data-idx', idx);
      b.textContent = t.name;
      wrap.appendChild(b);
    });
  }

  function loadTemplate(idx) {
    var t = TEMPLATES[idx];
    if (!t) return;
    lines = t.items.map(function (it) {
      return { name: it.name, dose: it.dose, qty: it.qty, unitCost: unitCostFor({ name: it.name }) };
    });
    $('dd-name').value = t.name;
    renderLines();
    recalc();
  }

  function renderSaved() {
    var ul = $('dd-saved');
    ul.innerHTML = '';
    var names = Object.keys(formulas).sort();
    if (!names.length) {
      var li = document.createElement('li');
      li.textContent = 'No saved formulas yet.';
      ul.appendChild(li);
      return;
    }
    names.forEach(function (name) {
      var f = formulas[name];
      var li = document.createElement('li');
      var loadBtn = document.createElement('button');
      loadBtn.type = 'button'; loadBtn.className = 'dd-load';
      loadBtn.setAttribute('data-name', name);
      loadBtn.textContent = name + ' \u2014 ' + money(f.price) + ' (' + (f.items || []).length + ' ingredients)';
      var del = document.createElement('button');
      del.type = 'button'; del.className = 'dd-del';
      del.setAttribute('data-name', name); del.setAttribute('aria-label', 'Delete ' + name);
      del.textContent = '\u00d7';
      li.appendChild(loadBtn); li.appendChild(del);
      ul.appendChild(li);
    });
  }

  function loadFormula(name) {
    var f = formulas[name];
    if (!f) return;
    lines = (f.items || []).map(function (it) {
      return { name: it.name, dose: it.dose || '', qty: it.qty == null ? 1 : it.qty, unitCost: unitCostFor({ name: it.name }) };
    });
    $('dd-name').value = name;
    $('dd-fee').value = f.fee == null ? 25 : f.fee;
    $('dd-price').value = f.price == null ? 0 : f.price;
    renderLines();
    recalc();
  }

  function saveFormula() {
    var name = $('dd-name').value.trim();
    if (!name) { alert('Give the formula a name first.'); $('dd-name').focus(); return; }
    if (!lines.length) { alert('Add at least one ingredient before saving.'); return; }
    refreshLineCosts();
    formulas[name] = {
      items: lines.map(function (l) { return { name: l.name, dose: l.dose, qty: num(l.qty), unitCost: unitCostFor(l) }; }),
      fee: num($('dd-fee').value),
      price: num($('dd-price').value),
      updatedAt: new Date().toISOString()
    };
    if (menuChecks[name] === undefined) menuChecks[name] = true;
    save(LS_FORMULAS, formulas);
    save(LS_MENU, menuChecks);
    renderSaved();
    renderMenu();
  }

  function newFormula() {
    lines = [];
    $('dd-name').value = '';
    $('dd-fee').value = 25;
    $('dd-price').value = 0;
    renderLines();
    recalc();
  }

  function renderLibTable() {
    var tb = $('dd-lib');
    tb.innerHTML = '';
    lib.forEach(function (ing, idx) {
      var tr = document.createElement('tr');
      var tdName = document.createElement('td');
      tdName.textContent = ing.name;
      var tdUnit = document.createElement('td');
      tdUnit.textContent = ing.unit;
      var tdCost = document.createElement('td');
      var inp = document.createElement('input');
      inp.type = 'number'; inp.className = 'dd-libcost'; inp.min = '0'; inp.step = '0.01';
      inp.value = ing.cost; inp.setAttribute('data-idx', idx);
      inp.setAttribute('aria-label', 'Cost for ' + ing.name);
      tdCost.appendChild(inp);
      var tdX = document.createElement('td');
      var x = document.createElement('button');
      x.type = 'button'; x.className = 'dd-remove';
      x.setAttribute('data-idx', idx); x.setAttribute('aria-label', 'Delete ' + ing.name);
      x.textContent = '\u00d7';
      tdX.appendChild(x);
      tr.appendChild(tdName); tr.appendChild(tdUnit); tr.appendChild(tdCost); tr.appendChild(tdX);
      tb.appendChild(tr);
    });
  }

  function renderMenu() {
    var wrap = $('dd-menulist');
    wrap.innerHTML = '';
    var names = Object.keys(formulas).sort();
    if (!names.length) {
      var p = document.createElement('p');
      p.className = 'dd-empty';
      p.textContent = 'Save a formula first \u2014 it will show up here for your printed menu card.';
      wrap.appendChild(p);
      return;
    }
    names.forEach(function (name) {
      var f = formulas[name];
      var div = document.createElement('div');
      div.className = 'dd-menu-item';
      var label = document.createElement('label');
      var cb = document.createElement('input');
      cb.type = 'checkbox'; cb.setAttribute('data-name', name);
      cb.checked = menuChecks[name] !== false;
      label.appendChild(cb);
      label.appendChild(document.createTextNode(name));
      var strong = document.createElement('strong');
      strong.textContent = money(f.price);
      div.appendChild(label); div.appendChild(strong);
      wrap.appendChild(div);
    });
  }

  function renderPrintDoc() {
    var names = Object.keys(formulas).sort().filter(function (n) { return menuChecks[n] !== false; });
    var today = new Date().toISOString().slice(0, 10);
    var itemsHtml = names.map(function (name) {
      var f = formulas[name];
      var ing = (f.items || []).map(function (it) {
        return esc(it.name) + (it.dose ? ' (' + esc(it.dose) + ')' : '');
      }).join(', ');
      return '<div class="dd-print-item"><div class="dd-print-top"><strong>' + esc(name) +
        '</strong><strong>' + esc(money(f.price)) + '</strong></div>' +
        (ing ? '<div class="dd-print-ing">' + ing + '</div>' : '') + '</div>';
    }).join('');
    $('dd-printdoc').innerHTML =
      '<h1>Drip Menu</h1><p class="dd-print-date">' + esc(today) + '</p>' +
      (itemsHtml || '<p>No formulas selected.</p>') +
      '<p class="dd-print-note">Prices include all ingredients and administration. Ask our team which drip fits your goals.</p>';
  }

  function exportJson() {
    var payload = { app: 'dripdesk', exportedAt: new Date().toISOString(), lib: lib, formulas: formulas };
    var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'dripdesk-formulas.json';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 100);
  }

  function importJson(file) {
    var reader = new FileReader();
    reader.onload = function () {
      try {
        var data = JSON.parse(reader.result);
        var ok = true;
        if (data.lib && Array.isArray(data.lib) && data.lib.length) {
          lib = data.lib.filter(function (x) { return x && x.name && x.unit != null && isFinite(parseFloat(x.cost)); });
        }
        if (data.formulas && typeof data.formulas === 'object') {
          Object.keys(data.formulas).forEach(function (k) {
            var f = data.formulas[k];
            if (f && Array.isArray(f.items)) {
              formulas[k] = f;
              if (menuChecks[k] === undefined) menuChecks[k] = true;
            }
          });
        }
        save(LS_LIB, lib); save(LS_FORMULAS, formulas); save(LS_MENU, menuChecks);
        refreshLineCosts();
        renderLibSelect(); renderLibTable(); renderLines(); renderSaved(); renderMenu(); recalc();
      } catch (e) { alert('Could not read that file \u2014 is it a DripDesk export?'); }
    };
    reader.readAsText(file);
  }

  var root = $('toolAppRoot');

  root.addEventListener('input', function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains('dd-dose')) {
      var row = t.closest('tr');
      lines[parseInt(row.getAttribute('data-idx'), 10)].dose = t.value;
      return;
    }
    if (t.classList && t.classList.contains('dd-qty')) {
      var rowQ = t.closest('tr');
      lines[parseInt(rowQ.getAttribute('data-idx'), 10)].qty = num(t.value);
    }
    if (t.classList && t.classList.contains('dd-libcost')) {
      var idx = parseInt(t.getAttribute('data-idx'), 10);
      lib[idx].cost = num(t.value);
      save(LS_LIB, lib);
      refreshLineCosts();
      renderLibSelect();
      renderLines();
    }
    recalc();
  });

  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'dd-add') {
      if (!lib.length) { alert('Add an ingredient to the library first.'); return; }
      var sel = $('dd-ing-select');
      var name = sel.value;
      var entry = libEntry(name);
      lines.push({ name: name, dose: '', qty: 1, unitCost: entry ? num(entry.cost) : 0 });
      renderLines();
      recalc();
      return;
    }
    if (t.id === 'dd-new') { newFormula(); return; }
    if (t.id === 'dd-save') { saveFormula(); return; }
    if (t.id === 'dd-use-suggest') {
      var target = num($('dd-margin-target').value);
      var ingCost = 0, i;
      for (i = 0; i < lines.length; i++) ingCost += lineCost(i);
      var total = ingCost + num($('dd-fee').value);
      var suggest = (target > 0 && target < 100) ? total / (1 - target / 100) : total;
      $('dd-price').value = suggest.toFixed(2);
      recalc();
      return;
    }
    if (t.id === 'dd-export') { exportJson(); return; }
    if (t.id === 'dd-lib-add') {
      var n = $('dd-lib-name').value.trim();
      var u = $('dd-lib-unit').value.trim() || 'dose';
      var c = num($('dd-lib-cost').value);
      if (!n) { alert('Give the ingredient a name.'); $('dd-lib-name').focus(); return; }
      if (libEntry(n)) { alert('That ingredient is already in the library.'); return; }
      lib.push({ name: n, unit: u, cost: c });
      save(LS_LIB, lib);
      $('dd-lib-name').value = ''; $('dd-lib-unit').value = ''; $('dd-lib-cost').value = '';
      renderLibSelect(); renderLibTable(); recalc();
      return;
    }
    if (t.id === 'dd-print') { renderPrintDoc(); window.print(); return; }
    if (t.classList && t.classList.contains('dd-remove')) {
      var dIdx = t.getAttribute('data-idx');
      if (t.closest('#dd-lib')) {
        var removed = lib[parseInt(dIdx, 10)];
        if (removed && confirm('Remove "' + removed.name + '" from the library?')) {
          lib.splice(parseInt(dIdx, 10), 1);
          save(LS_LIB, lib);
          renderLibSelect(); renderLibTable(); recalc();
        }
        return;
      }
      lines.splice(parseInt(dIdx, 10), 1);
      renderLines();
      recalc();
      return;
    }
    if (t.classList && t.classList.contains('dd-load')) { loadFormula(t.getAttribute('data-name')); return; }
    if (t.classList && t.classList.contains('dd-del')) {
      var delName = t.getAttribute('data-name');
      if (confirm('Delete "' + delName + '"?')) {
        delete formulas[delName];
        delete menuChecks[delName];
        save(LS_FORMULAS, formulas);
        save(LS_MENU, menuChecks);
        renderSaved(); renderMenu();
      }
      return;
    }
    if (t.closest && t.closest('#dd-templates')) {
      var btn = t.closest('button');
      if (btn) loadTemplate(parseInt(btn.getAttribute('data-idx'), 10));
      return;
    }
  });

  root.addEventListener('change', function (e) {
    var t = e.target;
    if (t.id === 'dd-import' && t.files && t.files[0]) {
      importJson(t.files[0]);
      t.value = '';
      return;
    }
    if (t.type === 'checkbox' && t.getAttribute('data-name')) {
      menuChecks[t.getAttribute('data-name')] = t.checked;
      save(LS_MENU, menuChecks);
    }
  });

  (function init() {
    renderLibSelect();
    renderTemplates();
    renderLibTable();
    renderSaved();
    renderMenu();
    var names = Object.keys(formulas);
    if (names.length) {
      names.sort(function (a, b) {
        return String(formulas[b].updatedAt || '').localeCompare(String(formulas[a].updatedAt || ''));
      });
      loadFormula(names[0]);
    } else {
      loadTemplate(0);
    }
    recalc();
  })();
})();
